    };
    // HTTP 500
    Mockito.when(cnxn.getResponseCode()).thenReturn(HttpURLConnection.HTTP_INTERNAL_ERROR);
    Mockito.when(cnxn.getOutputStream()).thenReturn(baos);
    // Should throw an RTE
    client.send(REQUEST.getBytes(StandardCharsets.UTF_8));
}

