@Test
public void testTicketRenewalTime() {
    RenewalTask renewal = mock(RenewalTask.class);
    when(renewal.shouldRenew(any(long.class), any(long.class), any(long.class))).thenCallRealMethod();
    long start = 0;
    long end = 200;
    long now = 100;
    assertFalse(renewal.shouldRenew(start, end, now));
    // Renewal should happen at 80%
    start = 0;
    end = 100;
    now = 80;
    assertTrue(renewal.shouldRenew(start, end, now));
    start = 5000;
    // One day
    end = start + 1000 * 60 * 60 * 24;
    // Ten minutes prior to expiration
    now = end - 1000 * 60 * 10;
    assertTrue(String.format("start=%d, end=%d, now=%d", start, end, now), renewal.shouldRenew(start, end, now));
}

