    end = start + 1000 * 60 * 60 * 24;
    // Ten minutes prior to expiration
    now = end - 1000 * 60 * 10;
    assertTrue(String.format("start=%d, end=%d, now=%d", start, end, now), renewal.shouldRenew(start, end, now));
}

